source('R/data.R');source('R/severity.R');source('R/household.R')
stopifnot(severity_result(2,3)$severity=='High',severity_result(NA,1)$severity=='Low',severity_result(NA,NA)$severity=='Unclassified')
stopifnot(!severity_result(1,1,899,TRUE)$override,severity_result(1,1,900,TRUE)$severity=='Critical',!severity_result(2,3,1000,FALSE)$override)
stopifnot(alert_status('2026-01-01','Yes',as.Date('2026-03-22'))=='Ongoing alert',alert_status('2026-01-01','Yes',as.Date('2026-03-23'))=='Pending closure')
u<-update_stage(list(conditions=2,protection=3),list(conditions=4,protection=NA));stopifnot(u$conditions==4,u$protection==3)
h<-read_history();stopifnot(nrow(h$registry)==18,nrow(h$evidence)==33,all(h$evidence$calculation_agrees,na.rm=TRUE))
stopifnot(sum(grepl('conflicting source ID',h$evidence$link_status))==3)
# Pure scenario fixtures; nothing here is an operational household.
x<-read.csv('data/household/synthetic_inputs.csv',colClasses='character',na.strings='',check.names=FALSE)
base<-x[which(x$hhh_sex=='male')[1],,drop=FALSE]
calc<-function(edits=list(),draft=TRUE) {
 z<-base;for(n in names(edits))z[[n]]<-edits[[n]]
 analyse_households(z,allow_draft=draft)
}
y<-calc();stopifnot(y$fcs_score==112,y$hhs_score==0,y$high_count_exact==0,y$highest_level_exact==1)
withheld<-calc(draft=FALSE);stopifnot(withheld$fcs_score==112,is.na(withheld$food_level_observed),is.na(withheld$high_count_lower))
zero<-as.list(setNames(rep('0',8),paste0('fcs_',c('cereals','pulses','vegetables','fruit','meat','milk','sugar','oil'),'_days')))
a<-calc(zero);stopifnot(a$fcs_score==0,a$fcs_category=='Poor',a$food_high_need==1)
p<-zero;p$fcs_pulses_days<-'7';stopifnot(calc(p)$fcs_score==21,calc(p)$fcs_category=='Poor')
p$fcs_cereals_days<-'7';stopifnot(calc(p)$fcs_score==35,calc(p)$fcs_category=='Borderline')
p<-zero;p$fcs_pulses_days<-'7';p$fcs_sugar_days<-'1';stopifnot(calc(p)$fcs_score==21.5,calc(p)$fcs_category=='Borderline')
a<-calc(list(fcs_oil_days=NA));stopifnot(is.na(a$fcs_score),a$food_classification_status=='partial',is.na(a$food_high_need))
a<-calc(list(fcs_oil_days='8'));stopifnot(is.na(a$fcs_score),grepl('invalid number',a$qa_flags))
a<-calc(list(hhs_1_occurrence='yes',hhs_1_frequency=NA));stopifnot(is.na(a$hhs_score),a$hhs_lower==0,a$hhs_upper==2,is.na(a$food_high_need))
a<-calc(list(hhs_1_occurrence='dk'));stopifnot(is.na(a$hhs_score))
a<-calc(list(hhs_1_occurrence='yes',hhs_1_frequency='often',hhs_2_occurrence='yes',hhs_2_frequency='often',hhs_3_occurrence='yes',hhs_3_frequency='rarely'))
stopifnot(a$hhs_score==5,a$hhs_extreme_review,a$food_level_observed==4)
a<-calc(list(shelter_type='sleeping_outdoors',shelter_condition=NA,shelter_issues=NA,shelter_cooking=NA));stopifnot(a$shelter_level_observed==4,a$shelter_classification_status=='partial',a$shelter_very_high_need==1)
a<-calc(list(shelter_issues='rain_leaks;other'));stopifnot(a$shelter_level_observed==3,a$shelter_high_need==1,is.na(a$shelter_very_high_need))
a<-calc(list(shelter_issues='none;rain_leaks'));stopifnot(grepl('exclusive',a$qa_flags),is.na(a$shelter_high_need))
stopifnot(calc(list(water_collection_minutes='30'))$water_service_category=='at_least_basic',calc(list(water_collection_minutes='31'))$water_service_category=='limited')
for(day in c(0,2,3,5,6,7)) stopifnot(calc(list(water_shortage_days_7d=as.character(day)))$wash_level_observed==c('0'=1,'2'=2,'3'=3,'5'=3,'6'=4,'7'=4)[[as.character(day)]])
a<-calc(list(sanitation_shared=NA));stopifnot(is.na(a$sanitation_service_category),is.na(a$wash_high_need))
a<-calc(list(sanitation_facility='no_facility___bush___field',sanitation_shared=NA));stopifnot(a$sanitation_service_category=='open_defecation',a$wash_high_need==1)
a<-calc(list(health_need_30d='yes',health_access='some',health_unresolved='yes',health_activity_impact=NA));stopifnot(a$health_level_observed==2,is.na(a$health_high_need),a$high_count_lower==0,a$high_count_upper==1,is.na(a$high_count_exact),a$high_count_concurrence==0)
a<-calc(list(health_need_30d='yes',health_access='none',health_unresolved='no'));stopifnot(a$health_level_observed==1,a$health_unmet_30d==1,a$health_current_unmet==0)
a<-calc(list(health_need_30d='yes',health_access='some',health_unresolved='yes',health_activity_impact='unable_usual_activities'));stopifnot(a$health_level_observed==4)
a<-calc(list(use_mode='registration_only'));stopifnot(is.na(a$fcs_score),is.na(a$high_count_exact),a$analysis_status=='excluded_nonbaseline')
a<-calc(list(lcsen_sell_house_land='no_exhausted'));stopifnot(a$lcs_class_observed==4,a$high_count_exact==0,grepl('sell_house_land',a$lcs_exhausted_strategies))
b<-count_bounds(c(1L,1L,NA_integer_,0L));stopifnot(b$lower==2,b$upper==3,is.na(b$exact),b$concurrence==1)
b<-count_bounds(rep(NA_integer_,4));stopifnot(b$lower==0,b$upper==4,is.na(b$exact),is.na(b$concurrence))
d<-analyse_households(x,allow_draft=TRUE);a<-aggregate_households(d,synthetic=TRUE)
stopifnot(nrow(a)>0,!any(a$suppressed),!any(c('hh_id','submission_id','fcs_score') %in% names(a)))
small<-aggregate_households(d[1:3,],synthetic=TRUE);stopifnot(all(small$suppressed),all(is.na(small$n_assessed)))
write.csv(a,'data/household/synthetic_aggregates.csv',row.names=FALSE,na='')
message('PASS: severity domains/override/status, source conflicts, FCS/HHS boundaries, four-sector rules, missingness/bounds, draft release gate, baseline exclusion, LCS separation and aggregate suppression.')
# Verified input wiring and baseline-to-RNA retained-domain provenance.
